-- The core copy's database (create-buddy --core, issue #107): the schema LearnBuddy's migrations
-- build, without the learning domain's tables. Generated by `pnpm core-check --write`
-- (packages/buddy-kit/src/baseline.ts) — never edit it by hand; core-check compares it with the
-- migrations through the catalog. In a core copy it is the only migration (0001_baseline.sql).

create extension if not exists pg_net;
create extension if not exists pg_cron;

-- Every object gets exactly the grants the dump lists below: Supabase grants new objects in
-- public to its API roles by default, and the migrations revoked part of that (0022). The dump
-- states the defaults the migrations left at its end.
alter default privileges in schema public revoke all on tables from anon, authenticated, service_role;
alter default privileges in schema public revoke all on sequences from anon, authenticated, service_role;
alter default privileges in schema public revoke all on functions from anon, authenticated, service_role;
create extension if not exists pgcrypto;

--
-- PostgreSQL database dump
--



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: public; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA IF NOT EXISTS public;


--
-- Name: lb_invoke_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lb_invoke_tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  _url text;
  _secret text;
begin
  select decrypted_secret into _url from vault.decrypted_secrets where name = 'lb_api_url';
  select decrypted_secret into _secret from vault.decrypted_secrets where name = 'lb_tick_secret';
  if _url is null or _secret is null then
    return;
  end if;
  perform net.http_post(
    url     := _url || '/internal/tick',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-tick-secret', _secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000
  );
end;
$$;


--
-- Name: lb_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lb_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

