    CONSTRAINT learners_birth_date_check CHECK (((birth_date >= '1920-01-01'::date) AND (birth_date <= '2030-12-31'::date))),
    CONSTRAINT learners_child_consent CHECK (((relation = 'self'::text) OR ((minor_consent_version IS NOT NULL) AND (minor_consent_at IS NOT NULL)))),
    CONSTRAINT learners_curriculum_region_check CHECK ((curriculum_region = ANY (ARRAY['bw'::text, 'by'::text, 'be'::text, 'bb'::text, 'hb'::text, 'hh'::text, 'he'::text, 'mv'::text, 'ni'::text, 'nw'::text, 'rp'::text, 'sl'::text, 'sn'::text, 'st'::text, 'sh'::text, 'th'::text, 'other'::text]))),
    CONSTRAINT learners_display_name_check CHECK (((length(display_name) >= 1) AND (length(display_name) <= 40))),
    CONSTRAINT learners_grade_check CHECK (((grade >= 1) AND (grade <= 13))),
    CONSTRAINT learners_grade_only_in_school CHECK (((grade IS NULL) OR (level = 'school'::text))),
    CONSTRAINT learners_level_check CHECK ((level = ANY (ARRAY['unknown'::text, 'school'::text, 'university'::text, 'adult'::text]))),
    CONSTRAINT learners_locale_check CHECK ((locale = ANY (ARRAY['de'::text, 'en'::text, 'fr'::text, 'es'::text, 'it'::text]))),
    CONSTRAINT learners_relation_check CHECK ((relation = ANY (ARRAY['self'::text, 'child'::text])))
);


--
-- Name: llm_calls; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.llm_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_id uuid,
    purpose text NOT NULL,
    model text NOT NULL,
    prompt_version text NOT NULL,
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    thought_tokens integer DEFAULT 0 NOT NULL,
    cost_micros bigint DEFAULT 0 NOT NULL,
    latency_ms integer DEFAULT 0 NOT NULL,
    outcome text NOT NULL,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cached_tokens integer DEFAULT 0 NOT NULL,
    decision_id uuid,
    round smallint,
    schema_variant text,
    streamed boolean DEFAULT false NOT NULL,
    first_token_ms integer,
    attempts smallint DEFAULT 1 NOT NULL,
    total_ms integer,
    CONSTRAINT llm_calls_outcome_check CHECK ((outcome = ANY (ARRAY['ok'::text, 'invalid_output'::text, 'error'::text, 'timeout'::text])))
);


--
-- Name: push_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.push_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_id uuid NOT NULL,
    token text NOT NULL,
    platform text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    invalid_reason text,
    registered_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    device_id text,
    CONSTRAINT push_tokens_device_id_check CHECK (((device_id IS NULL) OR (device_id ~ '^[A-Za-z0-9-]{16,64}$'::text))),
    CONSTRAINT push_tokens_platform_check CHECK ((platform = ANY (ARRAY['ios'::text, 'android'::text]))),
    CONSTRAINT push_tokens_status_check CHECK ((status = ANY (ARRAY['active'::text, 'invalid'::text]))),
    CONSTRAINT push_tokens_token_check CHECK (((length(token) >= 10) AND (length(token) <= 300)))
);


--
-- Name: speech_cache; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.speech_cache (
    learner_id uuid NOT NULL,
    key text NOT NULL,
    mime text NOT NULL,
    audio bytea NOT NULL,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT speech_cache_audio_check CHECK (((octet_length(audio) >= 1) AND (octet_length(audio) <= 2000000))),
    CONSTRAINT speech_cache_key_check CHECK ((key ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT speech_cache_mime_check CHECK ((mime = ANY (ARRAY['audio/mpeg'::text, 'audio/wav'::text])))
);


--
-- Name: speech_cache_shared; Type: TABLE; Schema: public; Owner: -
